import itertools as it, pickle, os
import numpy as np
import networkx as nx
import sympy as s
from scipy.optimize import linprog

edges=lambda n:list(it.combinations(range(n),2))
def mat(n,mask):
 A=np.zeros((n,n),dtype=int)
 for k,(i,j) in enumerate(edges(n)): A[i,j]=A[j,i]=(mask>>k)&1
 return A
def maskof(A,vs):
 return sum(int(A[vs[i],vs[j]])<<k for k,(i,j) in enumerate(edges(len(vs))))
def canon3(m):
 A=mat(3,m)
 return min(maskof(A,pp) for pp in [(0,1,2),(0,2,1)])
flags1=sorted(set(map(canon3,range(8)))); fi={f:i for i,f in enumerate(flags1)}
graphs=[nx.to_numpy_array(G,dtype=int) for G in nx.graph_atlas_g() if len(G)==5]
assert len(graphs)==34
books=[]; psd=[[],[],[],[],[]]
types=[0,1,3,7]
for A in graphs:
 H=np.zeros(64);E=np.zeros(64)
 M1=np.zeros((6,6)); Ms=[np.zeros((8,8)) for _ in types]
 for pp in it.permutations(range(5)):
  h=maskof(A,pp[:4]); col=h&1
  H[h]+=1/120
  if A[pp[0],pp[4]]==col and A[pp[1],pp[4]]==col:E[h]+=1/120
  f=fi[canon3(maskof(A,pp[:3]))]
  g=fi[canon3(maskof(A,[pp[0],pp[3],pp[4]]))]
  M1[f,g]+=1/120
  t=maskof(A,pp[:3])
  if t in types:
   k=types.index(t)
   f=sum(int(A[pp[i],pp[3]])<<i for i in range(3))
   g=sum(int(A[pp[i],pp[4]])<<i for i in range(3))
   Ms[k][f,g]+=1/120
 books.append((H,E))
 for j,M in enumerate([M1]+Ms):psd[j].append(M)
H=np.array([h for h,e in books]);E=np.array([e for h,e in books]); psd=list(map(np.array,psd))

p=s.symbols('p',positive=True)
def prob(A,parts):
 out=s.S.One
 for i,j in edges(len(parts)):
  q=p if parts[i]!=parts[j] else s.S.Zero
  out*=q if A[i,j] else 1-q
 return s.expand(out)

def flagvec1(part0):
 v=[0]*6
 for parts in it.product(range(3),repeat=2):
  for mm in range(8):
   v[fi[canon3(mm)]]+=prob(mat(3,mm),(part0,)+parts)/9
 return list(map(s.factor,v))
def v3(parts):
 v=[]
 for mm in range(8):
  total=0
  for z in range(3):
   zprob=1
   for i in range(3):
    q=p if parts[i]!=z else 0
    zprob*=q if (mm>>i)&1 else 1-q
   total+=zprob/3
  v.append(s.factor(total))
 return v
Vs=[s.Matrix([flagvec1(0)])]
for tt in types:
 T=mat(3,tt); vs=[]
 for parts in it.product(range(3),repeat=3):
  if prob(T,parts)!=0:
   v=v3(parts)
   if v not in vs:vs.append(v)
 Vs.append(s.Matrix(vs))
Ns=[s.Matrix.hstack(*V.nullspace()) for V in Vs]
print('flags',flags1,'null dims',[N.shape for N in Ns],flush=True)
with open('flags.pkl','wb') as f:pickle.dump((graphs,H,E,psd,Vs,Ns,p),f)

import numpy as np
from scipy.optimize import differential_evolution
rng=np.random.default_rng(12)
for alpha in [.17,.2,.205,.22,.3]:
 for k,nr in [(5,1),(6,2),(7,1),(7,3),(8,2),(9,3)]:
  ij=[(i,j) for i in range(k) for j in range(i+1,k) if j>=nr]
  def fun(z,ret=False):
   w=z[:k];w=w/w.sum();P=np.zeros((k,k));P[:nr,:nr]=1
   for v,(i,j) in zip(z[k:],ij):P[i,j]=P[j,i]=min(1,max(0,v))
   A=(P*w)@P;Q=1-P;B=(Q*w)@Q
   a=max([*A[:nr,:nr].diagonal()]+[A[i,j] for i,j in ij if P[i,j]>0])
   b=max([*B[nr:,nr:].diagonal()]+[B[i,j] for i,j in ij if i<nr and P[i,j]<1])
   return (1/max(a/alpha,b),w,P) if ret else max(a/alpha,b)
  best=(0,None)
  for seed in range(2):
   res=differential_evolution(fun,[(.000001,1)]*k+[(-.3,1.3)]*len(ij),popsize=6,maxiter=1800,tol=1e-7,rng=rng)
   v=fun(res.x,True)
   if v[0]>best[0]:best=v
  print(alpha,k,nr,best[0],flush=True)
  with open(f'opt_{alpha}_{k}_{nr}.npz','wb') as f:np.savez(f,c=best[0],w=best[1],P=best[2])
